"""Create local Compose credentials once, without printing or replacing them."""
import os
from pathlib import Path
import secrets


def create_env(path: Path) -> None:
    content = (
        "# Local values generated by scripts/setup_local.py; do not commit.\n"
        f"DB_PASSWORD={secrets.token_hex(24)}\n"
        f"JWT_SECRET={secrets.token_hex(32)}\n"
        "OLLAMA_CHAT_MODEL=llama3.2:3b\n"
        "OLLAMA_EMBEDDING_MODEL=mxbai-embed-large\n"
        "BACKEND_BIND_ADDRESS=127.0.0.1\n"
    )
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as output:
        output.write(content)


if __name__ == "__main__":
    try:
        create_env(Path(__file__).resolve().parents[1] / ".env")
    except FileExistsError:
        raise SystemExit("Existing .env kept. Check its settings against .env.example.")
    print("Created local .env. Existing database volumes must keep their original DB password.")
